class Solution:
    def isPalindrome(self, s: str) -> bool:
        l, r = 0, len(s) - 1
        lowercase = s.lower()

        while l <= r:
            if not lowercase[l].isalnum():
                l += 1
            elif not lowercase[r].isalnum():
                r -= 1
            elif lowercase[l] == lowercase[r]:
                l += 1
                r -= 1
            else:
                return False
        return True
